    max_heap = []
    for i in range(m - 1, n):
        heapq.heappush(max_heap, (-a[i], i))

    # Calculate dp table
    dp = [[-float('inf')] * (k + 1) for _ in range(n + 1)]
    dp[m][1] = prefix_sums[m]

    for j in range(2, k + 1):
        for i in range(m * j, n + 1):
            while max_heap and max_heap[0][1] < i - m:
                heapq.heappop(max_heap)
            if max_heap:
                dp[i][j] = max(dp[i][j], dp[i - m][j - 1] - prefix_sums[i - m] + prefix_sums[i] + max_heap[0][0])

    # Reconstruct the partition
    partition = []
    current = n
    for j in range(k, 0, -1):
        for i in range(m * j, current + 1):
            if dp[i][j] == dp[current][k]:
                partition.append(i - m)
                current = i - m
                break

    # Print the result
    print(-dp[n][k])
